-- 4. 插入标签关联（示例，假设标签 ID 已存在）
-- 假设标签 ID: 枸杞(1), 红枣(2), 山药(3), 补气养血(4), 滋阴润燥(5)
-- 这里使用子查询来匹配，确保准确性
SELECT r.id, t.id FROM `recipe` r, `recipe_tag` t 
WHERE r.title = '山药枸杞粥' AND t.tag_name IN ('山药', '枸杞', '补气养血');

SELECT r.id, t.id FROM `recipe` r, `recipe_tag` t 
WHERE r.title = '当归生姜羊肉汤' AND t.tag_name IN ('补气养血');

SELECT r.id, t.id FROM `recipe` r, `recipe_tag` t 
WHERE r.title = '银耳莲子羹' AND t.tag_name IN ('红枣', '滋阴润燥');

SELECT r.id, t.id FROM `recipe` r, `recipe_tag` t 
WHERE r.title = '黄芪炖母鸡' AND t.tag_name IN ('红枣', '补气养血');

SELECT r.id, t.id FROM `recipe` r, `recipe_tag` t 
WHERE r.title = '百合大枣粥' AND t.tag_name IN ('红枣');

-- 5. 为后续100+条食谱设置节气标签（通过 UPDATE 语句批量设置）
-- 立春推荐（宜辛甘发散，助阳气生发）
UPDATE `recipe` SET `suitable_seasons` = '立春' WHERE `title` IN ('党参红枣茶', '黑豆枸杞粥', '玫瑰花茶', '紫苏生姜茶', '山药枸杞粥');

-- 春分推荐（宜平和清淡，养肝健脾）
UPDATE `recipe` SET `suitable_seasons` = '春分' WHERE `title` IN ('百合大枣粥', '淮山排骨汤', '山药枸杞粥', '枸杞菊花茶', '百合莲子红豆粥');

